package com.example.feature.home.ui.modules

import android.util.Log
import org.json.JSONObject
import java.text.SimpleDateFormat
import java.util.Locale

object TnebBillStatusHtmlParser {

    private const val TAG = "TNEB"

    /**
     * Parses the JSON payload generated by the WebView's live DOM extractor.
     */
    fun parseJson(jsonString: String): TnebConsumerBillData? {
        return try {
            val json = JSONObject(jsonString)
            if (json.optBoolean("isError", false)) {
                val errorMsg = json.optString("errorMessage", "Unknown error")
                Log.e(TAG, "[TNEB] Parsing failed: Error reported in DOM payload: $errorMsg")
                return null
            }

            val consumerName = json.optString("consumerName", "").trim()
            val consumerNumber = json.optString("consumerNumber", "").trim()
            val region = json.optString("region", "").trim()
            val circle = json.optString("circle", "").trim()
            val section = json.optString("section", "").trim()
            val distribution = json.optString("distribution", "").trim()
            val serviceNumber = json.optString("serviceNumber", "").trim()
            val address = json.optString("address", "").trim()
            val serviceStatus = json.optString("serviceStatus", "").trim()
            val aadhar = json.optString("aadhar", "").trim()
            val gst = json.optString("gst", "").trim()
            val pan = json.optString("pan", "").trim()
            val phase = json.optString("phase", "").trim()
            val sanctionedLoad = json.optString("sanctionedLoad", "").trim()
            val tempReducedLoad = json.optString("tempReducedLoad", "").trim()
            val meterNumber = json.optString("meterNumber", "").trim()
            val securityDeposit = json.optString("securityDeposit", "").trim()
            val mcdDeposit = json.optString("mcdDeposit", "").trim()
            val serviceCategory = json.optString("serviceCategory", "").trim()
            val tariffCode = json.optString("tariffCode", "").trim()
            val consumerRating = json.optString("consumerRating", "").trim()
            val duesText = json.optString("duesText", "").trim()
            val isDuesNil = json.optBoolean("isDuesNil", false) || duesText.uppercase(Locale.US).contains("NIL")

            val billsArray = json.optJSONArray("records")
            val recordsList = mutableListOf<TnebBillRecord>()

            if (billsArray != null && billsArray.length() > 0) {
                Log.d(TAG, "[TNEB] Bill table detected")
                Log.d(TAG, "[TNEB] Number of records: ${billsArray.length()}")

                for (i in 0 until billsArray.length()) {
                    val obj = billsArray.getJSONObject(i)
                    val assessmentDate = obj.optString("assessmentDate", "").trim()
                    val entryDate = obj.optString("entryDate", "").trim()
                    val status = obj.optString("status", "NORMAL").trim()
                    val kwh = obj.optString("kwh", "").trim()
                    val kvah = obj.optString("kvah", "").trim()
                    val recordedDemand = obj.optString("recordedDemand", "").trim()
                    val powerFactor = obj.optString("powerFactor", "").trim()
                    val units = obj.optString("units", "0").trim()
                    val ccCharges = obj.optString("ccCharges", "0").trim()
                    val electricityTax = obj.optString("electricityTax", "0").trim()
                    val weldingCharges = obj.optString("weldingCharges", "0").trim()
                    val excessDemand = obj.optString("excessDemand", "0").trim()
                    val pfPenalty = obj.optString("pfPenalty", "0").trim()
                    val fixedCharges = obj.optString("fixedCharges", "0").trim()
                    val totalCharges = obj.optString("totalCharges", "0").trim()
                    val advancePaid = obj.optString("advancePaid", "0").trim()
                    val adjustment = obj.optString("adjustment", "0").trim()
                    val amountDue = obj.optString("amountDue", "0").trim()
                    val dueDate = obj.optString("dueDate", "").trim()
                    val amountPaid = obj.optString("amountPaid", "0").trim()
                    val receiptNumber = when {
                        obj.has("receiptNumber") -> obj.optString("receiptNumber", "")
                        obj.has("receiptNo") -> obj.optString("receiptNo", "")
                        else -> ""
                    }.trim()
                    val paymentDate = obj.optString("paymentDate", "").trim()

                    // Determine payment status:
                    // If dues is NIL for latest bill, or amountPaid equals amountDue, or receipt exists
                    val amtPaidNum = amountPaid.toDoubleOrNull() ?: 0.0
                    val amtDueNum = amountDue.toDoubleOrNull() ?: 0.0
                    val isPaid = (isDuesNil && i == 0) ||
                            (amtPaidNum > 0.0 && amtPaidNum >= amtDueNum) ||
                            receiptNumber.isNotBlank() ||
                            paymentDate.isNotBlank()

                    val period = formatPeriod(assessmentDate)

                    recordsList.add(
                        TnebBillRecord(
                            id = if (receiptNumber.isNotBlank()) receiptNumber else "BILL-${assessmentDate.replace("/", "")}",
                            assessmentDate = assessmentDate,
                            entryDate = entryDate,
                            status = status,
                            kwh = kwh,
                            kvah = kvah,
                            recordedDemand = recordedDemand,
                            powerFactor = powerFactor,
                            units = units,
                            ccCharges = ccCharges,
                            electricityTax = electricityTax,
                            weldingCharges = weldingCharges,
                            excessDemand = excessDemand,
                            pfPenalty = pfPenalty,
                            fixedCharges = fixedCharges,
                            totalCharges = totalCharges,
                            advancePaid = advancePaid,
                            adjustment = adjustment,
                            amountDue = amountDue,
                            dueDate = dueDate,
                            amountPaid = amountPaid,
                            receiptNumber = receiptNumber,
                            paymentDate = paymentDate,
                            isPaid = isPaid,
                            period = period
                        )
                    )
                }
            } else {
                Log.d(TAG, "[TNEB] No bill records array found in JSON")
            }

            val data = TnebConsumerBillData(
                consumerName = consumerName,
                consumerNumber = consumerNumber,
                region = region,
                circle = circle,
                section = section,
                distribution = distribution,
                serviceNumber = serviceNumber,
                address = address,
                serviceStatus = serviceStatus,
                aadhar = aadhar,
                gst = gst,
                pan = pan,
                phase = phase,
                sanctionedLoad = sanctionedLoad,
                tempReducedLoad = tempReducedLoad,
                meterNumber = meterNumber,
                securityDeposit = securityDeposit,
                mcdDeposit = mcdDeposit,
                serviceCategory = serviceCategory,
                tariffCode = tariffCode,
                consumerRating = consumerRating,
                duesText = duesText,
                isDuesNil = isDuesNil,
                bills = recordsList
            )

            logParsedData(data)
            data
        } catch (e: Exception) {
            Log.e(TAG, "[TNEB] Parsing failed: JSON parsing error: ${e.message}", e)
            null
        }
    }

    /**
     * Fallback native HTML parser that extracts consumer data and the 22-column bill table directly from raw HTML string.
     */
    fun parseHtml(html: String): TnebConsumerBillData? {
        Log.d(TAG, "[TNEB] HTML received, length: ${html.length}")
        return try {
            val lowerHtml = html.lowercase(Locale.US)
            if (!lowerHtml.contains("consdetails") && !lowerHtml.contains("consumption charges and collection details")) {
                Log.e(TAG, "[TNEB] Parsing failed: Not a recognized TNEB bill result page")
                return null
            }

            Log.d(TAG, "[TNEB] Bill page detected")

            // 1. Extract Consumer Name & Number
            val nameRegex = Regex("CONSUMER\\s*NAME\\s*[:\\s-]+\\s*([^<\\r\\n]+)", RegexOption.IGNORE_CASE)
            var consumerName = nameRegex.find(html)?.groupValues?.get(1)?.trim() ?: ""

            val numRegex = Regex("CONSUMER\\s*NUMBER\\s*[:\\s-]+\\s*([0-9]+)", RegexOption.IGNORE_CASE)
            var consumerNumber = numRegex.find(html)?.groupValues?.get(1)?.trim() ?: ""

            // 2. Extract Dues Text
            val duesRegex = Regex("DUES\\s*TO\\s*BE\\s*PAID\\s*IS\\s*[\"']?([^\"'\\r\\n<]+)[\"']?", RegexOption.IGNORE_CASE)
            var duesText = duesRegex.find(html)?.groupValues?.get(0)?.trim() ?: ""

            // 3. Extract General Consumer Metadata from Table 1 cells
            var region = ""
            var circle = ""
            var section = ""
            var distribution = ""
            var serviceNumber = ""
            var address = ""
            var serviceStatus = ""
            var phase = ""
            var sanctionedLoad = ""
            var meterNumber = ""
            var securityDeposit = ""
            var tariffCode = ""

            // Match all <td>...</td> tags
            val tdRegex = Regex("<td[^>]*>(.*?)</td>", setOf(RegexOption.IGNORE_CASE, RegexOption.DOT_MATCHES_ALL))
            val cleanCells = tdRegex.findAll(html).map { cleanHtml(it.groupValues[1]) }.toList()

            for (i in cleanCells.indices) {
                val cell = cleanCells[i].trim()
                val nextCell = if (i + 1 < cleanCells.size) cleanCells[i + 1].trim() else ""

                when {
                    cell.contains("CONSUMER NAME", ignoreCase = true) && consumerName.isBlank() -> consumerName = nextCell
                    cell.contains("CONSUMER NUMBER", ignoreCase = true) && consumerNumber.isBlank() -> consumerNumber = nextCell
                    cell.contains("DUES TO BE PAID IS", ignoreCase = true) && duesText.isBlank() -> duesText = cell
                    cell.equals("REGION", ignoreCase = true) -> region = nextCell
                    cell.equals("CIRCLE", ignoreCase = true) -> circle = nextCell
                    cell.equals("SECTION", ignoreCase = true) -> section = nextCell
                    cell.equals("DISTRIBUTION", ignoreCase = true) -> distribution = nextCell
                    cell.equals("SERVICE NUMBER", ignoreCase = true) -> serviceNumber = nextCell
                    cell.equals("ADDRESS", ignoreCase = true) -> address = nextCell
                    cell.equals("SERVICE STATUS", ignoreCase = true) -> serviceStatus = nextCell
                    cell.equals("PHASE", ignoreCase = true) -> phase = nextCell
                    cell.equals("SANCTIONED LOAD", ignoreCase = true) -> sanctionedLoad = nextCell
                    cell.equals("METER NUMBER", ignoreCase = true) -> meterNumber = nextCell
                    cell.contains("ACCD*", ignoreCase = true) -> securityDeposit = nextCell
                    cell.equals("TARIFF CODE", ignoreCase = true) || cell.equals("TARIFF", ignoreCase = true) -> tariffCode = nextCell
                }
            }

            val isDuesNil = duesText.uppercase(Locale.US).contains("NIL")

            // 4. Extract Table 2 rows (Consumption Charges and Collection Details)
            val recordsList = mutableListOf<TnebBillRecord>()
            val trRegex = Regex("<tr[^>]*>(.*?)</tr>", setOf(RegexOption.IGNORE_CASE, RegexOption.DOT_MATCHES_ALL))

            val rows = trRegex.findAll(html).toList()
            for (rowMatch in rows) {
                val rowHtml = rowMatch.groupValues[1]
                val rowCells = tdRegex.findAll(rowHtml).map { cleanHtml(it.groupValues[1]).trim() }.toList()

                // A valid billing record has at least 8 columns and starts with a date DD/MM/YYYY
                if (rowCells.size >= 8) {
                    val dateCandidate = rowCells[0]
                    if (dateCandidate.matches(Regex("\\d{2}[/\\-]\\d{2}[/\\-]\\d{4}"))) {
                        val assessmentDate = dateCandidate
                        val entryDate = rowCells.getOrElse(1) { "" }
                        val status = rowCells.getOrElse(2) { "NORMAL" }
                        val kwh = rowCells.getOrElse(3) { "" }
                        val kvah = rowCells.getOrElse(4) { "" }
                        val recordedDemand = rowCells.getOrElse(5) { "" }
                        val powerFactor = rowCells.getOrElse(6) { "" }
                        val units = rowCells.getOrElse(7) { "0" }
                        val ccCharges = rowCells.getOrElse(8) { "0" }
                        val electricityTax = rowCells.getOrElse(9) { "0" }
                        val weldingCharges = rowCells.getOrElse(10) { "0" }
                        val excessDemand = rowCells.getOrElse(11) { "0" }
                        val pfPenalty = rowCells.getOrElse(12) { "0" }
                        val fixedCharges = rowCells.getOrElse(13) { "0" }
                        val totalCharges = rowCells.getOrElse(14) { "0" }
                        val advancePaid = rowCells.getOrElse(15) { "0" }
                        val adjustment = rowCells.getOrElse(16) { "0" }
                        val amountDue = rowCells.getOrElse(17) { "0" }
                        val dueDate = rowCells.getOrElse(18) { "" }
                        val amountPaid = rowCells.getOrElse(19) { "0" }
                        val receiptNumber = rowCells.getOrElse(20) { "" }
                        val paymentDate = rowCells.getOrElse(21) { "" }

                        val amtPaidNum = amountPaid.toDoubleOrNull() ?: 0.0
                        val amtDueNum = amountDue.toDoubleOrNull() ?: 0.0
                        val isPaid = (isDuesNil && recordsList.isEmpty()) ||
                                (amtPaidNum > 0.0 && amtPaidNum >= amtDueNum) ||
                                receiptNumber.isNotBlank() ||
                                paymentDate.isNotBlank()

                        recordsList.add(
                            TnebBillRecord(
                                id = if (receiptNumber.isNotBlank()) receiptNumber else "BILL-${assessmentDate.replace("/", "")}",
                                assessmentDate = assessmentDate,
                                entryDate = entryDate,
                                status = status,
                                kwh = kwh,
                                kvah = kvah,
                                recordedDemand = recordedDemand,
                                powerFactor = powerFactor,
                                units = units,
                                ccCharges = ccCharges,
                                electricityTax = electricityTax,
                                weldingCharges = weldingCharges,
                                excessDemand = excessDemand,
                                pfPenalty = pfPenalty,
                                fixedCharges = fixedCharges,
                                totalCharges = totalCharges,
                                advancePaid = advancePaid,
                                adjustment = adjustment,
                                amountDue = amountDue,
                                dueDate = dueDate,
                                amountPaid = amountPaid,
                                receiptNumber = receiptNumber,
                                paymentDate = paymentDate,
                                isPaid = isPaid,
                                period = formatPeriod(assessmentDate)
                            )
                        )
                    }
                }
            }

            if (recordsList.isNotEmpty()) {
                Log.d(TAG, "[TNEB] Bill table detected")
                Log.d(TAG, "[TNEB] Number of records: ${recordsList.size}")
            }

            val result = TnebConsumerBillData(
                consumerName = consumerName,
                consumerNumber = consumerNumber,
                region = region,
                circle = circle,
                section = section,
                distribution = distribution,
                serviceNumber = serviceNumber,
                address = address,
                serviceStatus = serviceStatus,
                phase = phase,
                sanctionedLoad = sanctionedLoad,
                meterNumber = meterNumber,
                securityDeposit = securityDeposit,
                tariffCode = tariffCode,
                duesText = duesText,
                isDuesNil = isDuesNil,
                bills = recordsList
            )

            logParsedData(result)
            result
        } catch (e: Exception) {
            Log.e(TAG, "[TNEB] Parsing failed: Exception during HTML parsing: ${e.message}", e)
            null
        }
    }

    private fun logParsedData(data: TnebConsumerBillData) {
        val latest = data.latestBill
        if (latest != null) {
            Log.d(TAG, "[TNEB] Latest bill parsed")
            Log.d(TAG, "[TNEB] Amount due = ${latest.amountDue}")
            Log.d(TAG, "[TNEB] Units = ${latest.units}")
            Log.d(TAG, "[TNEB] Due date = ${latest.dueDate}")
            Log.d(TAG, "[TNEB] Status = ${if (latest.isPaid) "PAID" else "UNPAID"}")
        }
        Log.d(TAG, "[TNEB] Historical records = ${data.bills.size}")
        Log.d(TAG, "[TNEB] Sending parsed result to ViewModel")
    }

    private fun cleanHtml(raw: String): String {
        return raw.replace(Regex("<[^>]*>"), "")
            .replace("&nbsp;", " ")
            .replace("&amp;", "&")
            .replace("&#39;", "'")
            .replace("&quot;", "\"")
            .trim()
    }

    private fun formatPeriod(dateStr: String): String {
        return try {
            val parser = SimpleDateFormat("dd/MM/yyyy", Locale.US)
            val date = parser.parse(dateStr)
            if (date != null) {
                val formatter = SimpleDateFormat("MMM yyyy", Locale.US)
                formatter.format(date)
            } else {
                dateStr
            }
        } catch (_: Exception) {
            dateStr
        }
    }
}
